<?php
require_once '../../config/config.php'; require_once '../../config/database.php'; require_once '../../includes/access.php';
access_require_roles(array('Teacher')); $conn->set_charset('utf8mb4');
function portal_teacher_e($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
$teacher_id=(int)$_SESSION['linked_id'];$classes=array();$students=array();$subjects=array();$announcements=array();
$stmt=$conn->prepare("SELECT DISTINCT c.id,c.class_name FROM classes c LEFT JOIN teachers t ON t.class_incharge_id=c.id LEFT JOIN teacher_class_assignments a ON a.class_id=c.id AND a.teacher_id=? AND a.status=1 WHERE c.status=1 AND (t.id=? OR a.id IS NOT NULL) ORDER BY c.class_order");$stmt->bind_param('ii',$teacher_id,$teacher_id);$stmt->execute();$q=$stmt->get_result();while($x=$q->fetch_assoc())$classes[]=$x;$stmt->close();
$stmt=$conn->prepare("SELECT DISTINCT s.id,s.student_name,s.admission_no,c.class_name,sec.section_name FROM students s JOIN classes c ON c.id=s.class_id JOIN sections sec ON sec.id=s.section_id LEFT JOIN teachers t ON t.class_incharge_id=s.class_id LEFT JOIN teacher_class_assignments a ON a.class_id=s.class_id AND a.teacher_id=? AND a.status=1 WHERE s.status=1 AND (t.id=? OR a.id IS NOT NULL) ORDER BY c.class_order,sec.section_name,s.student_name");$stmt->bind_param('ii',$teacher_id,$teacher_id);$stmt->execute();$q=$stmt->get_result();while($x=$q->fetch_assoc())$students[]=$x;$stmt->close();
$stmt=$conn->prepare("SELECT DISTINCT s.subject_name,c.class_name FROM teacher_subjects ts JOIN subjects s ON s.id=ts.subject_id LEFT JOIN teacher_class_assignments a ON a.teacher_id=ts.teacher_id AND a.subject_id=ts.subject_id AND a.status=1 LEFT JOIN classes c ON c.id=a.class_id WHERE ts.teacher_id=? AND ts.status=1 ORDER BY s.subject_name,c.class_name");$stmt->bind_param('i',$teacher_id);$stmt->execute();$q=$stmt->get_result();while($x=$q->fetch_assoc())$subjects[]=$x;$stmt->close();
?>
<?php include '../../includes/header.php'; ?><?php include '../../includes/navbar.php'; ?><?php include '../../includes/sidebar.php'; ?>
<div class="content-wrapper"><section class="content-header"><div class="container-fluid"><h1><i class="fas fa-chalkboard-teacher"></i> Teacher Control Panel</h1></div></section><section class="content"><div class="container-fluid"><div class="alert alert-info">You can see and manage only your assigned classes and students.</div><div class="row"><div class="col-md-4"><div class="card"><div class="card-header bg-primary text-white">My Classes</div><div class="card-body"><ul><?php foreach($classes as $x):?><li><?=portal_teacher_e($x['class_name'])?></li><?php endforeach;?></ul></div></div></div><div class="col-md-8"><div class="card"><div class="card-header bg-success text-white">Attendance</div><div class="card-body"><a href="../attendance/index.php" class="btn btn-success">View / Mark / Edit Attendance</a><a href="../students/index.php" class="btn btn-primary ml-2">Edit Assigned Student Profiles</a></div></div><div class="card"><div class="card-header bg-info text-white">My Subjects</div><div class="card-body"><?php foreach($subjects as $x):?><span class="badge badge-info mr-2 mb-2"><?=portal_teacher_e($x['subject_name'].' - '.$x['class_name'])?></span><?php endforeach;?></div></div></div></div><div class="card"><div class="card-header bg-secondary text-white">My Students</div><div class="card-body p-0"><table class="table table-bordered mb-0"><tr><th>Admission</th><th>Name</th><th>Class</th><th>Section</th><th>Action</th></tr><?php foreach($students as $x):?><tr><td><?=portal_teacher_e($x['admission_no'])?></td><td><?=portal_teacher_e($x['student_name'])?></td><td><?=portal_teacher_e($x['class_name'])?></td><td><?=portal_teacher_e($x['section_name'])?></td><td><a class="btn btn-sm btn-primary" href="../students/edit.php?id=<?=(int)$x['id']?>">Edit Profile</a></td></tr><?php endforeach;?></table></div></div></div></section></div><?php include '../../includes/footer.php'; ?>
